function validate([root]) {
  if (!Array.isArray(root)) return 'root must be a level-order list.';
  if (root.length && root[0] === null) return 'A non-empty tree starts with its root value.';
  let slots = root.length ? 1 : 0;
  let nodes = 0;
  for (const value of root) {
    if (slots === 0) return 'The list has more entries than the tree has child slots.';
    slots--;
    if (value === null) continue;
    if (!Number.isInteger(value) || value < -100 || value > 100) return 'Node values are integers between -100 and 100.';
    nodes++;
    slots += 2;
  }
  if (nodes > 2000) return 'The tree has at most 2000 nodes.';
  return null;
}

