function generate(rand, size) {
  const large = size === 'large';
  // A level-order list may hold at most 2,000 entries, nulls included, so large trees retry with fewer nodes.
  for (let count = large ? 2000 : Math.floor(rand() * 9); ; count -= 100) {
    const span = large ? 100 : 5;
    const chain = !large && rand() < 0.25;
    const nodes = [];
    const open = [];
    for (let k = 0; k < count; k++) {
      const node = { val: Math.floor(rand() * (2 * span + 1)) - span, left: null, right: null };
      if (nodes.length) {
        // Attach to a random free child slot; a chain always extends the newest node.
        const index = chain ? open.length - 1 - Math.floor(rand() * 2) : Math.floor(rand() * open.length);
        const [parent, side] = open[index];
        open.splice(index, 1);
        parent[side] = node;
      }
      nodes.push(node);
      open.push([node, 'left'], [node, 'right']);
      if (chain && open.length > 2) open.splice(0, open.length - 2);
    }
    const out = [];
    const queue = count ? [nodes[0]] : [];
    for (let head = 0; head < queue.length; head++) {
      const node = queue[head];
      if (node === null) { out.push(null); continue; }
      out.push(node.val);
      queue.push(node.left, node.right);
    }
    while (out.length && out[out.length - 1] === null) out.pop();
    if (out.length <= 2000) return [out];
  }
}
